function processRefund(order, amount) {
  if (amount > order.total * 0.5) {
    requireManagerApproval(order.id, amount);
  }
  applyCredit(order.userId, amount);
  order.refunded += amount;
  return { success: true, newBalance: order.total - order.refunded };
}
